import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triu_matmul_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 16
#define THREAD_TILE 4
#define BLOCK_DIM 16
__global__ void triu_matmul_kernel(const float* __restrict__ A,
                                    const float* __restrict__ B,
                                    float* __restrict__ C,
                                    int N) {
    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_K][TILE_N];
    int blockRow = blockIdx.y * TILE_M;
    int blockCol = blockIdx.x * TILE_N;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * BLOCK_DIM + tx;
    float sum[THREAD_TILE][THREAD_TILE];
    #pragma unroll
    for (int i = 0; i < THREAD_TILE; i++) {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE; j++) {
            sum[i][j] = 0.0f;
        }
    }
    // Only compute if this block could contain non-zero upper-triangular contributions
    if (blockCol + TILE_N - 1 >= blockRow) {
        int numTiles = (N + TILE_K - 1) / TILE_K;
        for (int t = 0; t < numTiles; t++) {
            int k0 = t * TILE_K;
            // If entire k-tile has k < blockRow, A[row,k] is zero for all rows in this block
            if (k0 + TILE_K - 1 < blockRow) continue;
            // If entire k-tile has k > blockCol+TILE_N-1, B[k,col] is zero for all cols in this block
            if (k0 > blockCol + TILE_N - 1) break;
            // Load A tile (TILE_M x TILE_K) cooperatively
            #pragma unroll
            for (int i = 0; i < (TILE_M * TILE_K) / (BLOCK_DIM * BLOCK_DIM); i++) {
                int idx = tid + i * (BLOCK_DIM * BLOCK_DIM);
                int r = idx / TILE_K;
                int c = idx % TILE_K;
                int gRow = blockRow + r;
                int gCol = k0 + c;
                As[r][c] = (gRow < N && gCol < N) ? A[gRow * N + gCol] : 0.0f;
            }
            // Load B tile (TILE_K x TILE_N) cooperatively
            #pragma unroll
            for (int i = 0; i < (TILE_K * TILE_N) / (BLOCK_DIM * BLOCK_DIM); i++) {
                int idx = tid + i * (BLOCK_DIM * BLOCK_DIM);
                int r = idx / TILE_N;
                int c = idx % TILE_N;
                int gRow = k0 + r;
                int gCol = blockCol + c;
                Bs[r][c] = (gRow < N && gCol < N) ? B[gRow * N + gCol] : 0.0f;
            }
            __syncthreads();
            #pragma unroll
            for (int k = 0; k < TILE_K; k++) {
                float aFrag[THREAD_TILE];
                float bFrag[THREAD_TILE];
                #pragma unroll
                for (int i = 0; i < THREAD_TILE; i++) {
                    aFrag[i] = As[ty * THREAD_TILE + i][k];
                }
                #pragma unroll
                for (int j = 0; j < THREAD_TILE; j++) {
                    bFrag[j] = Bs[k][tx * THREAD_TILE + j];
                }
                #pragma unroll
                for (int i = 0; i < THREAD_TILE; i++) {
                    #pragma unroll
                    for (int j = 0; j < THREAD_TILE; j++) {
                        sum[i][j] += aFrag[i] * bFrag[j];
                    }
                }
            }
            __syncthreads();
        }
    }
    #pragma unroll
    for (int i = 0; i < THREAD_TILE; i++) {
        int row = blockRow + ty * THREAD_TILE + i;
        if (row >= N) continue;
        #pragma unroll
        for (int j = 0; j < THREAD_TILE; j++) {
            int col = blockCol + tx * THREAD_TILE + j;
            if (col < N) {
                C[row * N + col] = (row <= col) ? sum[i][j] : 0.0f;
            }
        }
    }
}
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    A = A.contiguous();
    B = B.contiguous();
    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());
    dim3 block(BLOCK_DIM, BLOCK_DIM);
    dim3 grid((N + TILE_N - 1) / TILE_N, (N + TILE_M - 1) / TILE_M);
    triu_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );
    return C;
}
"""

triu_matmul_cpp_source = r"""
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

triu_matmul_module = load_inline(
    name="triu_matmul_module",
    cpp_sources=triu_matmul_cpp_source,
    cuda_sources=triu_matmul_source,
    functions=["triu_matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for upper
    triangular matrices using a custom fused CUDA kernel that skips
    computation for tiles guaranteed to be zero due to the triangular
    structure, and masks the lower triangle of the output.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.triu_matmul = triu_matmul_module

    def forward(self, A, B):
        return self.triu_matmul.triu_matmul_cuda(A, B)


N = 4096

def get_inputs():
    A = torch.triu(torch.rand(N, N)).cuda()
    B = torch.triu(torch.rand(N, N)).cuda()
    return [A, B]

def get_init_inputs():
    return []

